// Flatten a Meta-shaped WhatsApp feed into one item per message:
//   { message_id, wa_id, name, lang_hint, text, received_at }
// Accepts three shapes: the full Meta webhook envelope (entry[].changes[].value.messages[]
// + contacts[].profile.name), the flat samples array (wa_id, id, timestamp, text.body,
// profile.name), or a single bare message object. Caps at MAX per run.
// received_at is stamped at INGESTION time (real wall-clock), never the sample's
// fictional Meta timestamp -- that keeps median_seconds_to_first_reply meaningful.
const MAX = 30;
const ES_WORDS = [
  "cita",
  "quiero",
  "gracias",
  "hola",
  "dias",
  "manana",
  "tarde",
  "jueves",
  "miercoles",
  "cuando",
  "puedo",
  "martes",
  "buenos",
  "buenas",
];
// Spanish accented / inverted-punctuation code points, matched by code so no
// non-ASCII bytes ever sit in this source file.
const ES_CODES = [0xe1, 0xe9, 0xed, 0xf3, 0xfa, 0xf1, 0xbf, 0xa1];

function hasAccentedSpanish(text) {
  for (let i = 0; i < text.length; i++) {
    if (ES_CODES.indexOf(text.charCodeAt(i)) >= 0) return true;
  }
  return false;
}

function guessLang(text) {
  const t = String(text || "");
  if (hasAccentedSpanish(t)) return "es";
  const lower = t.toLowerCase();
  for (const w of ES_WORDS) if (lower.indexOf(w) >= 0) return "es";
  return "en";
}

let raw = [];
for (const it of $input.all()) {
  let b = it.json;
  if (b && b.body && typeof b.body === "object" && (b.headers || b.query))
    b = b.body; // webhook wrapper

  if (b && Array.isArray(b.entry)) {
    for (const e of b.entry) {
      for (const ch of e.changes || []) {
        const v = ch.value || {};
        const nameByWa = {};
        for (const c of v.contacts || []) {
          if (c && c.wa_id) nameByWa[c.wa_id] = (c.profile || {}).name || null;
        }
        for (const m of v.messages || []) {
          raw.push({
            wa_id: m.from || m.wa_id,
            id: m.id,
            text: (m.text || {}).body || "",
            name: nameByWa[m.from] || null,
          });
        }
      }
    }
  } else if (Array.isArray(b)) {
    for (const m of b) {
      raw.push({
        wa_id: m.wa_id,
        id: m.id,
        text: (m.text || {}).body || m.body || "",
        name: (m.profile || {}).name || m.name || null,
      });
    }
  } else if (b && b.wa_id) {
    raw.push({
      wa_id: b.wa_id,
      id: b.id,
      text: (b.text || {}).body || b.body || "",
      name: (b.profile || {}).name || b.name || null,
    });
  }
}

const out = [];
for (const m of raw) {
  if (!m || !m.wa_id || !m.text) continue;
  out.push({
    json: {
      message_id: String(m.id || "").trim() || null,
      wa_id: String(m.wa_id).trim(),
      name: m.name || null,
      lang_hint: guessLang(m.text),
      text: String(m.text).trim(),
      received_at: new Date().toISOString(),
    },
  });
}
if (!out.length)
  throw new Error(
    "No messages in the feed. Expected a Meta-shaped payload or the samples array.",
  );
return out.slice(0, MAX);

// Deterministic ES/EN safety guard. Runs BEFORE the model. Code, not a prompt.
// Categories checked in order: emergency, symptoms, medication, diagnosis, price.
// First match wins and sets handoff=true + reason. No match -> handoff=false.
// Accented Spanish words are built from char codes so this file stays pure ASCII.
function ch(code) {
  return String.fromCharCode(code);
}
const O = ch(0xf3);
const A = ch(0xe1);
const ACC_INFECCION = "infecci" + O + "n";
const ACC_DIAGNOSTICO = "diagn" + O + "stico";
const ACC_CUANTO = "cu" + A + "nto cuesta";

const text = String($json.body || "").toLowerCase();

function has(s) {
  return text.indexOf(s) >= 0;
}

let handoff = false;
let reason = null;

if (has("emergencia") || /emergency/i.test(text)) {
  handoff = true;
  reason = "emergency";
} else if (
  /dolor|duele|fiebre|sangr|respirar|manchas|breathe|breathing|rash|bleeding|fever|\bpain\b/i.test(
    text,
  )
) {
  handoff = true;
  reason = "symptoms";
} else if (
  has("medicamento") ||
  has("dosis") ||
  has("ibuprofeno") ||
  /medication|dosage|\bdose\b|ibuprofen/i.test(text)
) {
  handoff = true;
  reason = "medication";
} else if (
  has(ACC_INFECCION) ||
  has(ACC_DIAGNOSTICO) ||
  has("grave") ||
  /diagnos|infection|is it serious|\bserious\b/i.test(text)
) {
  handoff = true;
  reason = "diagnosis";
} else if (
  has(ACC_CUANTO) ||
  has("precio") ||
  has("seguro") ||
  /\bprice\b|\bcost\b|how much|insurance/i.test(text)
) {
  handoff = true;
  reason = "price";
}

return {
  json: Object.assign({}, $json, {
    handoff: handoff,
    reason: reason,
  }),
};

// Extract the reply text and, when the agent actually booked a slot (via the
// book_slot tool), the booked slot id + start time from the intermediate steps.
const item = $json;
const guard = $("Safety guard").item.json;
const wa_id = guard.wa_id;
const message_id = guard.message_id;
const reply = item.output || item.text || "";

let booked_slot_id = null;
let booked_start = null;
const steps = Array.isArray(item.intermediateSteps)
  ? item.intermediateSteps
  : [];
for (const s of steps) {
  const toolName = s && s.action && s.action.tool;
  if (toolName !== "book_slot") continue;
  let obs = s.observation;
  let rows = [];
  try {
    const parsed = typeof obs === "string" ? JSON.parse(obs) : obs;
    rows = Array.isArray(parsed) ? parsed : (parsed && parsed.rows) || [];
  } catch (e) {
    rows = [];
  }
  if (rows.length) {
    booked_slot_id = rows[0].id || null;
    booked_start = rows[0].slot_start || null;
  }
}

return {
  json: {
    wa_id,
    message_id,
    reply,
    booked: !!booked_slot_id,
    slot_id: booked_slot_id,
    slot_start: booked_start,
  },
};

parameters.query:
WITH upd AS (
  UPDATE ep05_slots SET wa_id = $1 WHERE id = $2::integer AND $4::boolean = true RETURNING id
)
INSERT INTO ep05_bookings (wa_id, slot_id, message_id)
SELECT $1, $2::integer, $3 WHERE $4::boolean = true
RETURNING id, slot_id;

parameters.jsCode:
// One summary item, read straight off the execution panel.
function all(name) {
  try {
    return $(name)
      .all()
      .map(function (i) {
        return i.json;
      });
  } catch (e) {
    return [];
  }
}

const normalized = all("Normalize message");
const deduped = all("Dedupe on message.id");
const guarded = all("Safety guard");
const handoffRows = all("Handoff: insert handoff + outbox");
const agentOutbox = all("Insert outbox (agent reply)");
const bookingRows = all("Insert bookings (conditional)");

const patients = new Set(normalized.map((m) => m.wa_id));
const languages = Array.from(
  new Set(normalized.map((m) => m.lang_hint)),
).sort();

const handoffs_fired = guarded.filter((g) => g.handoff === true).length;
const duplicate_webhooks_ignored = Math.max(
  0,
  normalized.length - deduped.length,
);

const slotIds = bookingRows
  .map((r) => r.slot_id || r.id)
  .filter((v) => v !== null && v !== undefined);
const seen = new Set();
let double_bookings = 0;
for (const id of slotIds) {
  if (seen.has(id)) double_bookings++;
  else seen.add(id);
}

// median seconds to first reply: pair each patient's FIRST message received_at
// with the FIRST outbox row (handoff or agent reply) written for that wa_id.
const firstMsgByWa = {};
for (const m of guarded) {
  if (
    !firstMsgByWa[m.wa_id] ||
    new Date(m.received_at) < new Date(firstMsgByWa[m.wa_id])
  ) {
    firstMsgByWa[m.wa_id] = m.received_at;
  }
}
const outboxRows = handoffRows.concat(agentOutbox);
const firstReplyByWa = {};
for (const r of outboxRows) {
  const wa = r.wa_id;
  const t = r.written_at;
  if (!wa || !t) continue;
  if (!firstReplyByWa[wa] || new Date(t) < new Date(firstReplyByWa[wa])) {
    firstReplyByWa[wa] = t;
  }
}
const deltas = [];
for (const wa in firstMsgByWa) {
  if (firstReplyByWa[wa]) {
    const secs =
      (new Date(firstReplyByWa[wa]) - new Date(firstMsgByWa[wa])) / 1000;
    if (isFinite(secs) && secs >= 0) deltas.push(secs);
  }
}
deltas.sort((a, b) => a - b);
let median_seconds_to_first_reply = null;
if (deltas.length) {
  const mid = Math.floor(deltas.length / 2);
  median_seconds_to_first_reply =
    deltas.length % 2 ? deltas[mid] : (deltas[mid - 1] + deltas[mid]) / 2;
  median_seconds_to_first_reply =
    Math.round(median_seconds_to_first_reply * 10) / 10;
}

return [
  {
    json: {
      patients_simulated: patients.size,
      bookings_confirmed: bookingRows.length,
      median_seconds_to_first_reply,
      handoffs_fired,
      double_bookings,
      duplicate_webhooks_ignored,
      languages: languages.join(","),
    },
  },
];
